    }
}

impl IgnoreFile {
    fn matched(&self, path: &Path, is_dir: bool) -> Match {
        let rel = match path.strip_prefix(&self.base) {
            Ok(r) => r,
            Err(_) => return Match::None,
        };
        let rel_s: Vec<char> = rel.to_string_lossy().chars().collect();
        if rel_s.is_empty() {
