        } else if m_gi != Match::None {
            m_gi
        } else {
            m_ex
        };
        if m == Match::None && any_git {
            if let Some(g) = &self.global_parsed {
                m = g.matched(path, is_dir);
            }
        }
        m == Match::Ignore
    }

