// Inline scanning: split paragraph text into unbreakable wrapping units.

use crate::options::TemplateDelims;

#[derive(Debug, Clone, PartialEq)]
pub enum UnitKind {
    Text,
    /// A forced line break (rendered as the unit text, then a newline).
    HardBreak,
}

#[derive(Debug, Clone)]
pub struct Unit {
    pub text: String,
    pub kind: UnitKind,
    /// Byte ranges (within `text`) of a splittable link destination: (prefix_end, dest_end).
    pub link_split: Option<(usize, usize)>,
    /// Whether the unit came from a single atom that contained a newline.
    pub multiline: bool,
}

impl Unit {
    fn text(s: String) -> Self {
        Unit { text: s, kind: UnitKind::Text, link_split: None, multiline: false }
    }
}

pub struct Scanned {
    pub units: Vec<Unit>,
    /// Paragraph contains constructs we must not rewrap.
    pub unsupported: bool,
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t' || c == '\n'
}

/// Find the end of a code span starting at `i` (a backtick run). Returns index after closing run.
fn code_span_end(chars: &[char], i: usize) -> Option<usize> {
    let mut n = 0;
    while i + n < chars.len() && chars[i + n] == '`' {
        n += 1;
    }
    let mut j = i + n;
    while j < chars.len() {
        if chars[j] == '`' {
            let mut m = 0;
            while j + m < chars.len() && chars[j + m] == '`' {
                m += 1;
            }
            if m == n {
                return Some(j + m);
            }
            j += m;
        } else {
            j += 1;
        }
    }
    None
}

fn backtick_run(chars: &[char], i: usize) -> usize {
    let mut n = 0;
    while i + n < chars.len() && chars[i + n] == '`' {
        n += 1;
    }
    n
}

/// Find matching close bracket for '[' at i, honoring nesting, escapes and code spans.
fn bracket_end(chars: &[char], i: usize) -> Option<usize> {
    let mut depth = 0;
    let mut j = i;
    while j < chars.len() {
        let c = chars[j];
        if c == '\\' {
            j += 2;
            continue;
        }
        if c == '`' {
            match code_span_end(chars, j) {
                Some(e) => {
                    j = e;
                    continue;
                }
                None => {
                    j += backtick_run(chars, j);
                    continue;
                }
            }
        }
        if c == '[' {
            depth += 1;
        } else if c == ']' {
            depth -= 1;
            if depth == 0 {
                return Some(j);
            }
        }
        j += 1;
    }
    None
}

/// Find the closing ')' for a link destination starting after '(' at i.
fn paren_end(chars: &[char], i: usize) -> Option<usize> {
    let mut depth = 0;
    let mut j = i;
    let mut in_angle = false;
    while j < chars.len() {
        let c = chars[j];
        if c == '\\' {
            j += 2;
            continue;
        }
        if c == '<' && j == i + 1 {
            in_angle = true;
        } else if c == '>' && in_angle {
            in_angle = false;
        } else if !in_angle {
            if c == '"' || c == '\'' {
                // title string
                let q = c;
                let mut k = j + 1;
                while k < chars.len() && chars[k] != q {
                    if chars[k] == '\\' {
                        k += 1;
                    }
                    k += 1;
                }
                j = k + 1;
                continue;
            }
            if c == '(' {
                depth += 1;
            } else if c == ')' {
                depth -= 1;
                if depth == 0 {
                    return Some(j);
                }
            }
        }
        j += 1;
    }
    None
}

fn brace_end(chars: &[char], i: usize) -> Option<usize> {
    let mut j = i;
    while j < chars.len() {
        if chars[j] == '}' {
            return Some(j);
        }
        if chars[j] == '\n' && false {
            return None;
        }
        j += 1;
    }
    None
}

fn is_tag_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '-'
}

/// Parse an HTML open/close tag at i ('<'). Returns (end index after '>', tag name, is_close, self_closing).
pub fn html_tag_at(chars: &[char], i: usize) -> Option<(usize, String, bool, bool)> {
    if i >= chars.len() || chars[i] != '<' {
        return None;
    }
    let mut j = i + 1;
    let mut close = false;
    if j < chars.len() && chars[j] == '/' {
        close = true;
        j += 1;
    }
    if j >= chars.len() || !chars[j].is_ascii_alphabetic() {
        return None;
    }
    let ns = j;
    while j < chars.len() && is_tag_name_char(chars[j]) {
        j += 1;
    }
    let name: String = chars[ns..j].iter().collect::<String>().to_ascii_lowercase();
    if close {
        while j < chars.len() && is_ws(chars[j]) {
            j += 1;
        }
        if j < chars.len() && chars[j] == '>' {
            return Some((j + 1, name, true, false));
        }
        return None;
    }
    // attributes
    loop {
        let save = j;
        while j < chars.len() && is_ws(chars[j]) {
            j += 1;
        }
        if j >= chars.len() {
            return None;
        }
        if chars[j] == '>' {
            return Some((j + 1, name, false, false));
        }
        if chars[j] == '/' && j + 1 < chars.len() && chars[j + 1] == '>' {
            return Some((j + 2, name, false, true));
        }
        if j == save {
            return None;
        }
        // attribute name
        if !(chars[j].is_ascii_alphabetic() || chars[j] == '_' || chars[j] == ':') {
            return None;
        }
        while j < chars.len() && (chars[j].is_ascii_alphanumeric() || matches!(chars[j], '_' | '.' | ':' | '-')) {
            j += 1;
        }
        let save2 = j;
        while j < chars.len() && is_ws(chars[j]) {
            j += 1;
        }
        if j < chars.len() && chars[j] == '=' {
            j += 1;
            while j < chars.len() && is_ws(chars[j]) {
                j += 1;
            }
            if j >= chars.len() {
                return None;
            }
            let q = chars[j];
            if q == '"' || q == '\'' {
                j += 1;
                while j < chars.len() && chars[j] != q {
                    j += 1;
                }
                if j >= chars.len() {
                    return None;
                }
                j += 1;
            } else {
                let vs = j;
                while j < chars.len() && !is_ws(chars[j]) && !matches!(chars[j], '"' | '\'' | '=' | '<' | '>' | '`') {
                    j += 1;
                }
                if j == vs {
                    return None;
                }
            }
        } else {
            j = save2;
        }
    }
}

const VOID_TAGS: &[&str] = &[
    "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr",
];

/// Find the matching close tag for an element opened at `start` (after the open tag).
fn html_element_end(chars: &[char], start: usize, name: &str) -> Option<usize> {
    let mut depth = 1;
    let mut j = start;
    while j < chars.len() {
        if chars[j] == '<' {
            if let Some((e, n, close, selfc)) = html_tag_at(chars, j) {
                if n == name {
                    if close {
                        depth -= 1;
                        if depth == 0 {
                            return Some(e);
                        }
                    } else if !selfc {
                        depth += 1;
                    }
                }
                j = e;
                continue;
            }
        }
        j += 1;
    }
    None
}

/// Autolink `<scheme:...>` or `<email@host>`.
fn autolink_end(chars: &[char], i: usize) -> Option<usize> {
    let mut j = i + 1;
    let s = j;
    while j < chars.len() && chars[j] != '>' && !is_ws(chars[j]) && chars[j] != '<' {
        j += 1;
    }
    if j >= chars.len() || chars[j] != '>' {
        return None;
    }
    let inner: String = chars[s..j].iter().collect();
    if let Some(p) = inner.find(':') {
        let scheme = &inner[..p];
        if scheme.len() >= 2 && scheme.len() <= 32 && scheme.chars().next().unwrap().is_ascii_alphabetic()
            && scheme.chars().all(|c| c.is_ascii_alphanumeric() || matches!(c, '+' | '.' | '-'))
        {
            return Some(j + 1);
        }
    }
    if inner.contains('@') && !inner.starts_with('@') {
        return Some(j + 1);
    }
    None
}

/// Find the closing delimiter run for emphasis opened with `delim` repeated `n` times at i.
fn emphasis_end(chars: &[char], i: usize, delim: char, n: usize) -> Option<usize> {
    // Opening must be left-flanking: next char not whitespace.
    let after = i + n;
    if after >= chars.len() || is_ws(chars[after]) {
        return None;
    }
    if delim == '_' && i > 0 && chars[i - 1].is_alphanumeric() {
        return None;
    }
    let mut j = after;
    while j < chars.len() {
        let c = chars[j];
        if c == '\\' {
            j += 2;
            continue;
        }
        if c == '`' {
            match code_span_end(chars, j) {
                Some(e) => {
                    j = e;
                    continue;
                }
                None => {
                    j += backtick_run(chars, j);
                    continue;
                }
            }
        }
        if c == delim {
            let mut m = 0;
            while j + m < chars.len() && chars[j + m] == delim {
                m += 1;
            }
            // Closing must be right-flanking: previous char not whitespace.
            if m >= n && j > after && !is_ws(chars[j - 1]) {
                if delim == '_' && j + m < chars.len() && chars[j + m].is_alphanumeric() {
                    j += m;
                    continue;
                }
                if m == n || (m > n && n == 1) || m >= n {
                    return Some(j + n.min(m).max(n));
                }
            }
            j += m;
            continue;
        }
        j += 1;
    }
    None
}

fn template_end(chars: &[char], i: usize, delims: &TemplateDelims) -> Option<usize> {
    for (open, close) in &delims.pairs {
        let oc: Vec<char> = open.chars().collect();
        if i + oc.len() <= chars.len() && chars[i..i + oc.len()] == oc[..] {
            let cc: Vec<char> = close.chars().collect();
            let mut j = i + oc.len();
            let mut quote: Option<char> = None;
            let is_comment = open == "{#";
            while j < chars.len() {
                let c = chars[j];
                if c == '\n' {
                    return None;
                }
                if !is_comment {
                    if let Some(q) = quote {
                        if c == '\\' {
                            j += 2;
                            continue;
                        }
                        if c == q {
                            quote = None;
                        }
                        j += 1;
                        continue;
                    }
                    if c == '"' || c == '\'' {
                        quote = Some(c);
                        j += 1;
                        continue;
                    }
                }
                if j + cc.len() <= chars.len() && chars[j..j + cc.len()] == cc[..] {
                    return Some(j + cc.len());
                }
                j += 1;
            }
            return None;
        }
    }
    None
}

/// Math span `$...$` or `$$...$$` starting at i.
fn math_end(chars: &[char], i: usize) -> Option<usize> {
    if i + 1 < chars.len() && chars[i + 1] == '$' {
        let mut j = i + 2;
        while j + 1 < chars.len() {
            if chars[j] == '\\' {
                j += 2;
                continue;
            }
            if chars[j] == '$' && chars[j + 1] == '$' {
                return Some(j + 2);
            }
            j += 1;
        }
        return None;
    }
    if i + 1 >= chars.len() || is_ws(chars[i + 1]) {
        return None;
    }
    let mut j = i + 1;
    while j < chars.len() {
        if chars[j] == '\\' {
            j += 2;
            continue;
        }
        if chars[j] == '$' {
            if !is_ws(chars[j - 1]) && !(j + 1 < chars.len() && chars[j + 1].is_ascii_digit()) {
                return Some(j + 1);
            }
        }
        j += 1;
    }
    None
}

fn count_dollars(chars: &[char]) -> usize {
    let mut n = 0;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            i += 2;
            continue;
        }
        if c == '`' {
            match code_span_end(chars, i) {
                Some(e) => {
                    i = e;
                    continue;
                }
                None => {
                    i += backtick_run(chars, i);
                    continue;
                }
            }
        }
        if c == '$' {
            n += 1;
        }
        i += 1;
    }
    n
}

/// Collapse whitespace runs (including newlines) to single spaces.
pub fn collapse_ws(s: &str) -> String {
    let mut out = String::new();
    let mut prev_ws = false;
    for c in s.chars() {
        if is_ws(c) {
            if !prev_ws {
                out.push(' ');
            }
            prev_ws = true;
        } else {
            out.push(c);
            prev_ws = false;
        }
    }
    out
}

pub fn scan(text: &str, templates: &TemplateDelims) -> Scanned {
    let chars: Vec<char> = text.chars().collect();
    let mut units: Vec<Unit> = Vec::new();
    let mut cur = String::new();
    let mut cur_multi = false;
    let mut cur_split: Option<(usize, usize)> = None;
    let mut cur_has_link = 0;
    let mut unsupported = false;
    if count_dollars(&chars) % 2 == 1 {
        unsupported = true;
    }
    let n = chars.len();
    let mut i = 0;
    let push_cur = |units: &mut Vec<Unit>, cur: &mut String, multi: &mut bool, split: &mut Option<(usize, usize)>, links: &mut usize| {
        if !cur.is_empty() {
            let mut u = Unit::text(std::mem::take(cur));
            u.multiline = *multi;
            u.link_split = if *links == 1 { *split } else { None };
            units.push(u);
        }
        *multi = false;
        *split = None;
        *links = 0;
    };
    while i < n {
        let c = chars[i];
        if c == '\n' {
            // Hard break detection: trailing two spaces or backslash before newline.
            let line_before: String = cur.clone();
            let _ = line_before;
            // Check spaces before the newline in source.
            let mut k = i;
            let mut spaces = 0;
            while k > 0 && chars[k - 1] == ' ' {
                spaces += 1;
                k -= 1;
            }
            if cur.ends_with('\\') && spaces == 0 && !cur.ends_with("\\\\") {
                push_cur(&mut units, &mut cur, &mut cur_multi, &mut cur_split, &mut cur_has_link);
                if let Some(last) = units.last_mut() {
                    last.kind = UnitKind::HardBreak;
                }
            } else if spaces >= 2 {
                push_cur(&mut units, &mut cur, &mut cur_multi, &mut cur_split, &mut cur_has_link);
                units.push(Unit { text: "\\".into(), kind: UnitKind::HardBreak, link_split: None, multiline: false });
            } else {
                push_cur(&mut units, &mut cur, &mut cur_multi, &mut cur_split, &mut cur_has_link);
            }
            i += 1;
            continue;
        }
        if c == ' ' || c == '\t' {
            push_cur(&mut units, &mut cur, &mut cur_multi, &mut cur_split, &mut cur_has_link);
            i += 1;
            continue;
        }
        if c == '\\' && i + 1 < n {
            if chars[i + 1] == '\n' {
                cur.push('\\');
                i += 1;
                continue;
            }
            cur.push(c);
            cur.push(chars[i + 1]);
            i += 2;
            continue;
        }
        // Templates.
        if c == '{' || c == '<' {
            if let Some(e) = template_end(&chars, i, templates) {
                cur.extend(&chars[i..e]);
                i = e;
                continue;
            }
        }
        if c == '`' {
            match code_span_end(&chars, i) {
                Some(e) => {
                    let s: String = chars[i..e].iter().collect();
                    if s.contains('\n') {
                        cur_multi = true;
                    }
                    cur.push_str(&s);
                    i = e;
                    continue;
                }
                None => {
                    unsupported = true;
                    let r = backtick_run(&chars, i);
                    cur.extend(&chars[i..i + r]);
                    i += r;
                    continue;
                }
            }
        }
        if c == '$' {
            if let Some(e) = math_end(&chars, i) {
                let s: String = chars[i..e].iter().collect();
                if s.contains('\n') {
                    cur_multi = true;
                }
                cur.push_str(&s);
                i = e;
                continue;
            }
            if i + 1 < n && chars[i + 1] == '$' {
                unsupported = true;
                cur.push_str("$$");
                i += 2;
                continue;
            }
            cur.push('$');
            i += 1;
            continue;
        }
        if c == '<' {
            if i + 3 < n && chars[i + 1] == '!' && chars[i + 2] == '-' && chars[i + 3] == '-' {
                unsupported = true;
                cur.push(c);
                i += 1;
                continue;
            }
            if i + 1 < n && (chars[i + 1] == '?' || chars[i + 1] == '!') {
                unsupported = true;
                cur.push(c);
                i += 1;
                continue;
            }
            if let Some(e) = autolink_end(&chars, i) {
                cur.extend(&chars[i..e]);
                i = e;
                continue;
            }
            if let Some((e, name, close, selfc)) = html_tag_at(&chars, i) {
                if !close && !selfc && !VOID_TAGS.contains(&name.as_str()) {
                    if let Some(end) = html_element_end(&chars, e, &name) {
                        let s: String = chars[i..end].iter().collect();
                        cur.push_str(&s);
                        i = end;
                        continue;
                    }
                }
                let s: String = chars[i..e].iter().collect();
                cur.push_str(&s);
                i = e;
                continue;
            }
            cur.push(c);
            i += 1;
            continue;
        }
        if c == '!' && i + 1 < n && chars[i + 1] == '[' {
            if let Some((e, split)) = scan_link(&chars, i + 1) {
                let s: String = chars[i..e].iter().collect();
                let multi = s.contains('\n');
                let s = if multi { collapse_link_text(&s) } else { s };
                if let Some((a, b)) = split {
                    let base = cur.len();
                    let pre: String = chars[i..a].iter().collect();
                    let dest: String = chars[a..b].iter().collect();
                    let pre = if multi { collapse_ws(&pre) } else { pre };
                    cur_split = Some((base + pre.len(), base + pre.len() + dest.len()));
                    cur.push_str(&pre);
                    cur.push_str(&dest);
                    let rest: String = chars[b..e].iter().collect();
                    cur.push_str(&rest);
                } else {
                    cur.push_str(&s);
                }
                cur_has_link += 1;
                i = e;
                continue;
            }
        }
        if c == '^' && i + 1 < n && chars[i + 1] == '[' {
            if let Some(e) = bracket_end(&chars, i + 1) {
                let s: String = chars[i..=e].iter().collect();
                let s = if s.contains('\n') { collapse_ws(&s) } else { s };
                cur.push_str(&s);
                i = e + 1;
                continue;
            }
        }
        if c == '[' {
            if let Some((e, split)) = scan_link(&chars, i) {
                let s: String = chars[i..e].iter().collect();
                let multi = s.contains('\n');
                if let Some((a, b)) = split {
                    let base = cur.len();
                    let pre: String = chars[i..a].iter().collect();
                    let pre = if multi { collapse_ws(&pre) } else { pre };
                    let dest: String = chars[a..b].iter().collect();
                    cur_split = Some((base + pre.len(), base + pre.len() + dest.len()));
                    cur.push_str(&pre);
                    cur.push_str(&dest);
                    let rest: String = chars[b..e].iter().collect();
                    cur.push_str(&rest);
                } else {
                    let s = if multi { collapse_link_text(&s) } else { s };
                    cur.push_str(&s);
                }
                cur_has_link += 1;
                i = e;
                continue;
            }
            unsupported = true;
            cur.push(c);
            i += 1;
            continue;
        }
        if c == '*' || c == '_' {
            let mut r = 0;
            while i + r < n && chars[i + r] == c {
                r += 1;
            }
            let try_n = r.min(3);
            if let Some(e) = emphasis_end(&chars, i, c, try_n) {
                let s: String = chars[i..e].iter().collect();
                let s = if s.contains('\n') { collapse_ws(&s) } else { s };
                cur.push_str(&s);
                i = e;
                continue;
            }
            cur.extend(&chars[i..i + r]);
            i += r;
            continue;
        }
        if c == '~' && i + 1 < n && chars[i + 1] == '~' {
            // Strikethrough.
            let mut j = i + 2;
            let mut found = None;
            while j + 1 < n {
                if chars[j] == '~' && chars[j + 1] == '~' {
                    found = Some(j + 2);
                    break;
                }
                j += 1;
            }
            match found {
                Some(e) => {
                    let s: String = chars[i..e].iter().collect();
                    let s = if s.contains('\n') { collapse_ws(&s) } else { s };
                    cur.push_str(&s);
                    i = e;
                }
                None => {
                    unsupported = true;
                    cur.push_str("~~");
                    i += 2;
                }
            }
            continue;
        }
        cur.push(c);
        i += 1;
    }
    push_cur(&mut units, &mut cur, &mut cur_multi, &mut cur_split, &mut cur_has_link);
    Scanned { units, unsupported }
}

fn collapse_link_text(s: &str) -> String {
    collapse_ws(s)
}

/// Scan a link/span starting with '[' at i. Returns (end, split range of destination).
fn scan_link(chars: &[char], i: usize) -> Option<(usize, Option<(usize, usize)>)> {
    let close = bracket_end(chars, i)?;
    let mut e = close + 1;
    let mut split = None;
    if e < chars.len() && chars[e] == '(' {
        let pe = paren_end(chars, e)?;
        // Destination without title is splittable.
        let inner: String = chars[e + 1..pe].iter().collect();
        let inner_t = inner.trim();
        if !inner_t.is_empty() && !inner_t.contains(char::is_whitespace) {
            split = Some((e + 1, pe));
        }
        e = pe + 1;
    } else if e < chars.len() && chars[e] == '[' {
        let be = bracket_end(chars, e)?;
        e = be + 1;
    }
    if e < chars.len() && chars[e] == '{' {
        if let Some(be) = brace_end(chars, e) {
            e = be + 1;
        }
    }
    Some((e, split))
}

/// Tokens that must not begin a wrapped line (they would change block structure).
pub fn dangerous_start(tok: &str) -> bool {
    let t = tok;
    if t.is_empty() {
        return false;
    }
    let c0 = t.chars().next().unwrap();
    if c0 == '>' || c0 == '|' || c0 == ':' {
        return true;
    }
    if t == "~" {
        return true;
    }
    if t.chars().all(|c| c == '#') && t.len() <= 6 {
        return true;
    }
    if t == "-" || t == "+" || t == "*" {
        return true;
    }
    if t.len() >= 2 && t.chars().all(|c| c == '-') {
        return true;
    }
    if t.chars().all(|c| c == '=') {
        return true;
    }
    if t.len() >= 3 && (t.chars().all(|c| c == '*') || t.chars().all(|c| c == '_')) {
        return true;
    }
    // Ordered list markers.
    let body: &str = if let Some(b) = t.strip_suffix('.') {
        b
    } else if let Some(b) = t.strip_suffix(')') {
        if let Some(b2) = b.strip_prefix('(') {
            if is_list_label(b2) {
                return true;
            }
            ""
        } else {
            b
        }
    } else {
        ""
    };
    if !body.is_empty() && is_list_label(body) {
        return true;
    }
    // Reference definitions.
    if c0 == '[' {
        if let Some(p) = t.find("]:") {
            if p > 0 {
                return true;
            }
        }
    }
    // HTML tags.
    if c0 == '<' {
        let chars: Vec<char> = t.chars().collect();
        if html_tag_at(&chars, 0).is_some() {
            return true;
        }
    }
    false
}

fn is_list_label(b: &str) -> bool {
    if b.chars().all(|c| c.is_ascii_digit()) && !b.is_empty() {
        return true;
    }
    if b.chars().count() == 1 && b.chars().next().unwrap().is_ascii_alphabetic() {
        return true;
    }
    if !b.is_empty() && (b.chars().all(|c| "ivxlcdm".contains(c)) || b.chars().all(|c| "IVXLCDM".contains(c))) {
        return true;
    }
    false
}

