// Line filling for Markdown prose.

use super::inline::{dangerous_start, Unit, UnitKind};
use super::width::width;
use crate::options::Wrap;

#[derive(Debug, Clone)]
struct Piece {
    text: String,
    /// Forced alone on its own line with extra indentation (split link destination).
    dest: bool,
    /// Forces a new line before this piece.
    newline_before: bool,
    hard_break: bool,
}

fn merge_dangerous(units: &[Unit]) -> Vec<Unit> {
    let mut out: Vec<Unit> = Vec::new();
    for u in units {
        if u.kind == UnitKind::Text && !out.is_empty() && dangerous_start(&u.text) {
            let prev = out.last_mut().unwrap();
            if prev.kind == UnitKind::Text {
                prev.text.push(' ');
                prev.text.push_str(&u.text);
                prev.link_split = None;
                continue;
            }
        }
        out.push(u.clone());
    }
    out
}

fn to_pieces(units: &[Unit], max_width: usize) -> Vec<Piece> {
    let mut pieces = Vec::new();
    for u in units {
        if u.kind == UnitKind::HardBreak {
            pieces.push(Piece { text: u.text.clone(), dest: false, newline_before: false, hard_break: true });
            continue;
        }
        if let Some((a, b)) = u.link_split {
            if width(&u.text) > max_width {
                let pre = &u.text[..a];
                let dest = &u.text[a..b];
                let post = &u.text[b..];
                pieces.push(Piece { text: pre.to_string(), dest: false, newline_before: false, hard_break: false });
                pieces.push(Piece { text: dest.to_string(), dest: true, newline_before: true, hard_break: false });
                pieces.push(Piece { text: post.to_string(), dest: false, newline_before: true, hard_break: false });
                continue;
            }
        }
        pieces.push(Piece { text: u.text.clone(), dest: false, newline_before: false, hard_break: false });
    }
    pieces
}

/// Greedy fill. `first_width` applies to the first line, `width` to the rest.
/// Destination pieces are emitted on their own line prefixed by two spaces.
pub fn fill(units: &[Unit], first_width: usize, rest_width: usize) -> Vec<String> {
    let units = merge_dangerous(units);
    let pieces = to_pieces(&units, rest_width);
    let mut lines: Vec<String> = Vec::new();
    let mut line = String::new();
    let mut line_w = 0usize;
    let mut started = false;
    for p in pieces {
        let avail = if lines.is_empty() { first_width } else { rest_width };
        if p.dest {
            if started {
                lines.push(std::mem::take(&mut line));
            }
            lines.push(format!("  {}", p.text));
            line_w = 0;
            started = false;
            continue;
        }
        if p.newline_before && started {
            lines.push(std::mem::take(&mut line));
            line_w = 0;
            started = false;
        }
        let pw = width(&p.text);
        if p.hard_break && p.text == "\\" {
            // Trailing-space hard break: attach to the current line.
            if started {
                line.push(' ');
            }
            line.push_str(&p.text);
            lines.push(std::mem::take(&mut line));
            line_w = 0;
            started = false;
            continue;
        }
        if !started {
            line.push_str(&p.text);
            line_w = pw;
            started = true;
        } else if line_w + 1 + pw <= avail {
            line.push(' ');
            line.push_str(&p.text);
            line_w += 1 + pw;
        } else {
            lines.push(std::mem::take(&mut line));
            line.push_str(&p.text);
            line_w = pw;
        }
        if p.hard_break {
            lines.push(std::mem::take(&mut line));
            line_w = 0;
            started = false;
        }
    }
    if started || lines.is_empty() {
        lines.push(line);
    }
    lines
}

/// Units of a paragraph on one line per hard-break segment.
pub fn join_all(units: &[Unit]) -> Vec<String> {
    fill(units, usize::MAX / 2, usize::MAX / 2)
}

fn strip_closers(s: &str) -> &str {
    s.trim_end_matches(['"', '\'', ')', ']', '\u{201d}', '\u{2019}', '*', '_'])
}

fn ends_sentence(tok: &str) -> bool {
    let lower = tok.to_lowercase();
    if lower == "e.g." || lower == "i.e." {
        return false;
    }
    let t = tok.trim_end_matches(['"', '\'', ')', '\u{201d}', '\u{2019}']);
    let _ = strip_closers;
    t.ends_with('.') || t.ends_with('!') || t.ends_with('?')
}

/// Escape a token that would start a block construct at the start of a line.
fn escape_sentence_start(tok: &str) -> Option<String> {
    if tok == "-" || tok == "+" || tok == "*" {
        return Some(format!("\\{}", tok));
    }
    if tok.starts_with('#') && tok.chars().all(|c| c == '#') && tok.len() <= 6 {
        return Some(format!("\\{}", tok));
    }
    if tok.starts_with('>') {
        return Some(format!("\\{}", tok));
    }
    // Ordered markers: escape the delimiter.
    for d in ['.', ')'] {
        if let Some(b) = tok.strip_suffix(d) {
            let label = b.strip_prefix('(').unwrap_or(b);
            let ok = (!label.is_empty() && label.chars().all(|c| c.is_ascii_digit()))
                || (label.chars().count() == 1 && label.chars().next().unwrap().is_ascii_alphabetic())
                || (!label.is_empty() && (label.chars().all(|c| "ivxlcdm".contains(c)) || label.chars().all(|c| "IVXLCDM".contains(c))));
            if ok && !b.starts_with('(') {
                return Some(format!("{}\\{}", b, d));
            }
        }
    }
    None
}

/// Split units into sentences (each a list of units).
fn sentences(units: &[Unit]) -> Vec<Vec<Unit>> {
    let mut out: Vec<Vec<Unit>> = Vec::new();
    let mut cur: Vec<Unit> = Vec::new();
    let n = units.len();
    let mut i = 0;
    while i < n {
        let u = units[i].clone();
        let is_break = u.kind == UnitKind::HardBreak;
        cur.push(u.clone());
        if is_break {
            out.push(std::mem::take(&mut cur));
            i += 1;
            continue;
        }
