            let next = &units[i + 1];
            if next.kind == UnitKind::Text && dangerous_start(&next.text) {
                if let Some(esc) = escape_sentence_start(&next.text) {
                    out.push(std::mem::take(&mut cur));
                    let mut nu = next.clone();
                    nu.text = esc;
                    cur.push(nu);
                    i += 2;
                    // The escaped token may itself end a sentence.
                    continue;
                }
                // Cannot start a line here; keep in the same sentence.
                i += 1;
                continue;
            }
            out.push(std::mem::take(&mut cur));
        }
        i += 1;
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

pub fn wrap_units(units: &[Unit], wrap: Wrap, first_width: usize, rest_width: usize) -> Vec<String> {
    match wrap {
        Wrap::Column(_) => fill(units, first_width, rest_width),
        Wrap::Paragraph | Wrap::None => join_all(units),
        Wrap::Sentence(n) => {
            let mut lines = Vec::new();
            for s in sentences(units) {
                match n {
                    Some(_) => {
                        let fw = if lines.is_empty() { first_width } else { rest_width };
                        lines.extend(fill(&s, fw, rest_width));
                    }
                    None => lines.extend(join_all(&s)),
