    let mut cur_w = 0usize;
    let line_w = |v: &Vec<String>| -> usize {
        if v.is_empty() {
            0
        } else {
            v.iter().map(|t| width(t)).sum::<usize>() + v.len() - 1
        }
    };
    for p in pieces {
        let avail = if lines.is_empty() { first_width } else { rest_width };
        if p.dest {
            if !cur.is_empty() {
                lines.push(cur.join(" "));
                cur.clear();
            }
            lines.push(format!("  {}", p.text));
            cur_w = 0;
            continue;
        }
        if p.newline_before && !cur.is_empty() {
            lines.push(cur.join(" "));
            cur.clear();
            cur_w = 0;
        }
        if p.hard_break && p.text == "\\\\" {
            cur.push(p.text.clone());
            lines.push(cur.join(" "));
            cur.clear();
            cur_w = 0;
            continue;
        }
        let pw = width(&p.text);
        if cur.is_empty() {
            cur.push(p.text.clone());
            cur_w = pw;
        } else if cur_w + 1 + pw <= avail {
            cur.push(p.text.clone());
            cur_w += 1 + pw;
        } else if !dangerous_start(&p.text) {
            lines.push(cur.join(" "));
            cur.clear();
            cur.push(p.text.clone());
            cur_w = pw;
        } else {
            let rest_avail = rest_width;
            let last_w = width(cur.last().unwrap());
            if cur.len() >= 2 && last_w + 1 + pw <= rest_avail {
                let last = cur.pop().unwrap();
                lines.push(cur.join(" "));
                cur.clear();
                cur.push(last);
                cur.push(p.text.clone());
                cur_w = line_w(&cur);
