    ("html", "prettier"),
    ("prettier-html", "prettier"),
    ("js", "prettier"),
    ("javascript", "prettier"),
    ("prettier-js", "prettier"),
    ("jsx", "prettier"),
    ("prettier-jsx", "prettier"),
    ("ts", "prettier"),
    ("typescript", "prettier"),
    ("prettier-ts", "prettier"),
