    ("prettier-jsonc", "prettier"),", "+    ("json5", "prettier"),", "+    ("prettier-json5", "prettier"),", "+    ("graphql", "prettier"),", "+    ("gql", "prettier"),", "+    ("graphqls", "prettier"),", "+    ("prettier-graphql", "prettier"),", "+    ("css", "prettier"),", "+    ("prettier-css", "prettier"),", "+    ("scss", "prettier"),", "+    ("prettier-scss", "prettier"),", "+    ("less", "prettier"),", "+    ("prettier-less", "prettier"),", "+    ("postcss", "prettier"),", "+    ("pcss", "prettier"),", "+    ("prettier-postcss", "prettier"),", "+    ("html", "prettier"),", "+    ("prettier-html", "prettier"),", "+    ("js", "prettier"),", "+    ("javascript", "prettier"),", "+    ("prettier-js", "prettier"),", "+    ("jsx", "prettier"),", "+    ("prettier-jsx", "prettier"),", "+    ("ts", "prettier"),", "+    ("typescript", "prettier"),", "+    ("prettier-ts", "prettier"),", "+    ("tsx", "prettier"),", "+    ("prettier-tsx", "prettier"),", "+];", "+", "+pub fn formatter_program(name: &str) -> Option<&'static str> {", "+    KNOWN_FORMATTERS.iter().find(|(n, _)| *n == name).map(|(_, p)| *p)", "+}", "+", "+fn shrink_wrap(o: &Options, indent: usize) -> Options {", "+    let mut o = o.clone();", "+    o.wrap = match o.wrap {", "+        Wrap::Column(n) => Wrap::Column(n.saturating_sub(indent).max(1)),", "+        Wrap::Sentence(Some(n)) => Wrap::Sentence(Some(n.saturating_sub(indent).max(1))),", "+        w => w,", "+    };", "+    o", "+}", "+", "+struct Edit {", "+    start: usize,", "+    end: usize,", "+    text: String,", "+}", "+", "+pub fn format_source_file(src: &str, opts: &Options, is_r: bool, notes: &mut Vec<Diagnostic>) -> Result<String, Diagnostic> {", "+    let toks = if is_r { scan_r(src) } else { scan_python(src) };", "+    let lines = Lines::new(src);", "+    let line_texts: Vec<&str> = {", "+        let mut v: Vec<&str> = src.split('\n').collect();", "+        if src.ends_with('\n') {", "+            v.pop();", "+        }", "+        v", "+    };", "+    let nlines = line_texts.len();", "+    // Own-line comments.", "+    let mut own: Vec<OwnComment> = Vec::new();", "+    for &c in &toks.comments {", "+        let l = lines.line_of(c);", "+        let ls = lines.starts[l];", "+        if src[ls..c].trim().is_empty() {", "+            own.push(OwnComment { line: l, indent: src[ls..c].to_string(), text: src[c..line_end(src, c)].to_string() });", "+        }", "+    }", "+    let own_at = |line: usize| -> Option<&OwnComment> { own.iter().find(|o| o.line == line) };", "+    // Skip file.", "+    for o in &own {", "+        if let Some(Ok(Directive::SkipFile)) = parse_directive(&o.text, opts) {", "+            return Ok(src.to_string());", "+        }", "+    }", "+    let eof_pos = || -> (usize, usize) {", "+        if nlines == 0 {", "+            return (1, 1);", "+        }", "+        (nlines, line_texts[nlines - 1].chars().count() + 1)", "+    };", "+    let mut edits: Vec<Edit> = Vec::new();", "+    let mut consumed_lines: Vec<bool> = vec![false; nlines + 1];", "+    let mut off = false;", "+    let mut skip_next = false;", "+    let mut i = 0;", "+    while i < own.len() {", "+        let o = own[i].clone();", "+        if consumed_lines[o.line] {", "+            i += 1;", "+            continue;", "+        }", "+        if let Some(d) = parse_directive(&o.text, opts) {", "+            let d = match d {", "+                Ok(d) => d,", "+                Err(m) => return Err(Diagnostic { line: o.line + 1, col: 1, msg: m }),", "+            };", "+            match d {", "+                Directive::Off => {", "+                    off = true;", "+                    i += 1;", "+                    continue;", "+                }", "+                Directive::On => {", "+                    off = false;", "+                    i += 1;", "+                    continue;", "+                }", "+                Directive::Skip => {", "+                    skip_next = true;", "+                    i += 1