ne] + o.indent.len() + o.text.len();", "+                    let target = find_string_target(&toks, after, is_r);", "+                    match target {", "+                        Some(Ok(s)) => {", "+                            let fl = lines.line_of(s.content_start);", "+                            for l in lines.line_of(s.start)..=lines.line_of(s.end.saturating_sub(1)) {", "+                                consumed_lines[l] = true;", "+                            }", "+                            let _ = fl;", "+                            if !skip_next {", "+                                if let Some(e) = format_string_target(src, &lines, &s, &mo, is_r, notes)? {", "+                                    edits.push(e);", "+                                }", "+                            }", "+                            skip_next = false;", "+                        }", "+                        Some(Err(pos)) => {", "+                            let l = lines.line_of(pos);", "+                            let col = src[lines.starts[l]..pos].chars().count() + 1;", "+                            return Err(Diagnostic { line: l + 1, col, msg: "fmt: markdown has no target".into() });", "+                        }", "+                        None => {", "+                            let (l, c) = eof_pos();", "+                            return Err(Diagnostic { line: l, col: c, msg: "fmt: markdown has no target".into() });", "+                        }", "+                    }", "+                    i += 1;", "+                    continue;", "+                }", "+                Directive::Embedded(name) => {", "+                    let after = lines.starts[o.line] + o.indent.len() + o.text.len();", "+                    let target = find_string_target(&toks, after, is_r);", "+                    match target {", "+                        Some(Ok(s)) => {", "+                            let cl = content_first_line(src, &lines, &s);", "+                            let prog = formatter_program(&name);", "+                            match prog {", "+                                None => {", "+                                    return Err(Diagnostic { line: cl + 1, col: 1, msg: format!("unknown embedded formatter: {}", name) });", "+                                }", "+                                Some(p) => {", "+                                    if opts.diagnostics && !opts.skip_embedded {", "+                                        notes.push(Diagnostic { line: cl + 1, col: 1, msg: format!("missing optional embedded formatter `{}`; preserved source", p) });", "+                                    }", "+                                }", "+                            }", "+                            for l in lines.line_of(s.start)..=lines.line_of(s.end.saturating_sub(1)) {", "+                                consumed_lines[l] = true;", "+                            }", "+                        }", "+                        Some(Err(pos)) => {", "+                            let l = lines.line_of(pos);", "+                            let col = src[lines.starts[l]..pos].chars().count() + 1;", "+                            return Err(Diagnostic { line: l + 1, col, msg: format!("fmt: {} has no target", name) });", "+                        }", "+                        None => {", "+                            let (l, c) = eof_pos();", "+                            return Err(Diagnostic { line: l, col: c, msg: format!("fmt: {} has no target", name) });", "+                        }", "+                    }", "+                    i += 1;", "+                    continue;", "+                }", "+            }", "+        }", "+        // Hashpipe block.", "+        if o.text.starts_with("#|") {", "+            let mut block = vec![o.clone()];", "+            let mut l = o.line + 1;", "+            while let Some(c) = own_at(l) {", "+                if !c.text.starts_with("#|") || c.indent != o.indent {", "+       