if(sub==="yaml"){if(src.includes("\t"))bad.push("TAB");errs=chk(src);}
else{if(lines[0]==="---"){const end=lines.indexOf("---",1);if(end<0)bad.push("FM-UNCLOSED");else errs=chk(lines.slice(1,end).join("\n"));}let open=null,dO=0,dC=0;for(const l of lines){const m=l.match(/^\s*(`{3,}|~{3,})/);if(m){if(!open)open=m[1];else if(m[1][0]===open[0]&&m[1].length>=open.length&&/^\s*[`~]+\s*$/.test(l))open=null;continue;}if(open)continue;if(/^:{3,}\s*$/.test(l))dC++;else if(/^:{3,}\s*[{\w.]/.test(l))dO++;}if(open)bad.push("FENCE-UNCLOSED");if(dO!==dC)bad.push("DIVS-"+dO+"/"+dC);}
const fb=[];if(sub==="yaml"){lines.forEach((l,i)=>{const m=l.match(/^(\s*)[\]}]/);if(!m)return;let depth=0;for(let k=i;k>=0;k--){const t=lines[k].replace(/#.*$/,"");for(let c=t.length-1;c>=0;c--){if(t[c]==="]"||t[c]==="}")depth++;else if(t[c]==="["||t[c]==="{"){depth--;if(depth===0){const om=lines[k].match(/^(\s*)(- +)?/);const owner=om[1].length+(om[2]&&/^\s*- +[^\s\[{]/.test(lines[k])?om[2].length:0);if(m[1].length<=owner)fb.push("FLOW-INDENT line "+(i+1)+" (opened line "+(k+1)+"): col "+m[1].length+" <= owner col "+owner);k=-1;break;}}}}});if(fb.length)bad.push("FLOW-INDENT");}
console.log(sub+"/"+f+"\t"+lines.length+"\t"+(errs.length?"YAML-ERR":"ok")+(bad.length?"\t"+bad.join(","):""));for(const e of errs.concat(fb))console.log("    "+e);}}
' '\.Rmd$'

