const mine=["render.yaml","amplify.yml","decap-cms-config.yml","pre-commit-config.yaml","conda-environment.yml","spring-application.yml","prometheus-rules.yml","dependabot.yml","azure-pipelines.yml","goreleaser.yaml"];
function chk(src){const d=YAML.parseAllDocuments(src,{strict:true,uniqueKeys:true});const a=Array.isArray(d)?d:[];const e=[];for(const x of a){for(const y of x.errors)e.push(y.code+": "+y.message.split("\n")[0]);for(const y of x.warnings)if(y.code!=="TAG_RESOLVE_FAILED")e.push("warn "+y.code+": "+y.message.split("\n")[0]);}return {e,n:a.length};}
for(const f of mine){const src=fs.readFileSync(path.join("/tmp/corpus2/yaml",f),"utf8");const lines=src.split("\n");if(src.endsWith("\n"))lines.pop();const bad=[];if(src.includes("\r"))bad.push("CR");if(src.includes("\t"))bad.push("TAB");if(src.includes("�"))bad.push("BADUTF8");if(lines.length<80||lines.length>300)bad.push("LINES");if(!src.endsWith("\n"))bad.push("NO-FINAL-NL");
const r=chk(src);const fb=[];lines.forEach((l,i)=>{const m=l.match(/^(\s*)[\]}]/);if(!m)return;let depth=0;for(let k=i;k>=0;k--){const t=lines[k].replace(/#.*$/,"");for(let c=t.length-1;c>=0;c--){if(t[c]==="]"||t[c]==="}")depth++;else if(t[c]==="["||t[c]==="{"){depth--;if(depth===0){const om=lines[k].match(/^(\s*)(- +)?/);const owner=om[1].length+(om[2]&&/^\s*- +[^\s\[{]/.test(lines[k])?om[2].length:0);if(m[1].length<=owner)fb.push("FLOW-INDENT line "+(i+1));k=-1;break;}}}}});
