const fs=require("fs"),path=require("path");
const Q1="\x27";
function check(text){
  const lines=text.split("\n");const out=[];
  let blockOwner=-1,depth=0,fOwner=-1,fLine=-1,quote=null,qOwner=-1,qLine=-1;
  for(let i=0;i<lines.length;i++){
    const line=lines[i];const ind=line.match(/^ */)[0].length;const tr=line.trim();
    if(/^(---|\.\.\.)(\s|$)/.test(line)){blockOwner=-1;depth=0;quote=null;continue;}
    if(blockOwner>=0){if(tr===""||ind>blockOwner)continue;blockOwner=-1;}
    if(tr==="")continue;
    if(depth>0&&!quote&&!tr.startsWith("#")&&ind<=fOwner)out.push((i+1)+": flow continuation col "+ind+" <= owner col "+fOwner+" (opened line "+(fLine+1)+")");
    if(quote&&ind<=qOwner)out.push((i+1)+": quoted continuation col "+ind+" <= owner col "+qOwner+" (opened line "+(qLine+1)+")");
    const mm=line.match(/^( *)((?:- +)*)/);const contentCol=mm[0].length;
    const lastDashCol=mm[2].length?mm[1].length+mm[2].replace(/ +$/,"").lastIndexOf("-"):-1;
    let j=0;
    for(;j<line.length;j++){
      const c=line[j];
      if(quote){if(quote===Q1){if(c===Q1){if(line[j+1]===Q1){j++;continue;}quote=null;}}else{if(c==="\\"){j++;continue;}if(c==="\""){quote=null;}}continue;}
      if(c==="#"&&(j===0||/\s/.test(line[j-1])))break;
      const prev=line.slice(0,j).replace(/\s+$/,"");const pc=prev.length?prev[prev.length-1]:"";
      const vs=prev.length===0||pc===":"||pc==="-"||pc==="?"||(depth>0&&(pc==="["||pc==="{"||pc===","));
      if((c==="\""||c===Q1)&&vs){quote=c;if(depth===0){qOwner=(pc==="-")?lastDashCol:(pc===":"?contentCol:ind-1);qLine=i;}continue;}
      if(c==="["||c==="{"){if(depth>0||vs){if(depth===0){fOwner=(pc==="-")?lastDashCol:(pc===":"?contentCol:ind-1);fLine=i;}depth++;}continue;}
      if((c==="]"||c==="}")&&depth>0){depth--;continue;}
    }
    const code=line.slice(0,j);
    if(depth===0&&!quote){const bm=code.match(/(^ *(?:- +)*|: +)([|>])[0-9+-]{0,2} *$/);if(bm){blockOwner=bm[1].startsWith(":")?contentCol:(lastDashCol>=0?lastDashCol:ind-1);}}
  }
  if(depth>0)out.push("EOF: unclosed flow opened line "+(fLine+1));
  if(quote)out.push("EOF: unclosed quote opened line "+(qLine+1));
  return out;
}
let total=0;
for(const f of fs.readdirSync("/tmp/corpus2/yaml").sort()){const r=check(fs.readFileSync("/tmp/corpus2/yaml/"+f,"utf8"));total++;if(r.length){console.log("yaml/"+f);r.forEach(x=>console.log("   "+x));}}
for(const f of fs.readdirSync("/tmp/corpus2/md").sort()){const lines=fs.readFileSync("/tmp/corpus2/md/"+f,"utf8").split("\n");if(lines[0]!=="---")continue;const end=lines.indexOf("---",1);const r=check(lines.slice(1,end).join("\n"));total++;if(r.length){console.log("md/"+f+" (front matter, line numbers offset by 1)");r.forEach(x=>console.log("   "+x));}}
console.log("checked",total);
'

