start=s.index('/// Pandoc grid tables: refit column widths to their contents.')
s=s[:start]+'''/// Pandoc grid tables: refit column widths to their contents.
pub fn format_grid_table(lines: &[String], widths: TableWidths) -> Option<Vec<String>> {
    if widths == TableWidths::Preserve {
        return None;
    }
    let first = lines.first()?.trim_end();
    if !first.starts_with('+') || !first.ends_with('+') {
        return None;
    }
    let ncols = first.matches('+').count() - 1;
    if ncols == 0 {
        return None;
    }
    enum Row {
        Sep(char, Vec<(bool, bool)>),
        Content(Vec<String>),
    }
    let mut rows = Vec::new();
    for l in lines {
        let t = l.trim_end();
        if t.starts_with('+') {
            if !t.ends_with('+') {
                return None;
            }
            let segs: Vec<&str> = t[1..t.len() - 1].split('+').collect();
            if segs.len() != ncols {
                return None;
            }
            let mut fill = '-';
            let mut colons = Vec::new();
            for seg in segs {
                let left = seg.starts_with(':');
                let right = seg.ends_with(':') && seg.len() > 1;
                let inner = seg.trim_matches(':');
                if inner.is_empty() || !(inner.chars().all(|x| x == '-') || inner.chars().all(|x| x == '=')) {
                    return None;
                }
                if inner.starts_with('=') {
                    fill = '=';
                }
                colons.push((left, right));
            }
            rows.push(Row::Sep(fill, colons));
        } else if t.starts_with('|') {
            if !t.ends_with('|') {
                return None;
            }
            let cells = split_row(t);
            if cells.len() != ncols {
                return None;
            }
            rows.push(Row::Content(cells));
        } else {
            return None;
        }
    }
    let mut w = vec![0usize; ncols];
    for r in &rows {
        if let Row::Content(cells) = r {
            for (c, cell) in cells.iter().enumerate() {
                w[c] = w[c].max(width(cell));
            }
        }
    }
    let mut out = Vec::new();
    for r in &rows {
        match r {
            Row::Sep(fill, colons) => {
                let mut line = String::from("+");
                for c in 0..ncols {
                    let n = w[c] + 2;
                    let (l, rr) = colons[c];
                    let mut seg: Vec<char> = std::iter::repeat(*fill).take(n).collect();
                    if l {
                        seg[0] = ':';
                    }
                    if rr {
                        seg[n - 1] = ':';
                    }
                    line.extend(seg);
                    line.push('+');
                }
                out.push(line);
            }
            Row::Content(cells) => {
                let mut line = String::from("|");
                for c in 0..ncols {
                    let pad = w[c] - width(&cells[c]);
                    line.push(' ');
                    line.push_str(&cells[c]);
                    line.push_str(&" ".repeat(pad + 1));
                    line.push('|');
                }
                out.push(line);
            }
        }
    }
    Some(out)
}
'''
