// Minimal TOML reader for yamark.toml.

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Str(_) => "string",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Bool(_) => "boolean",
            Value::Array(_) => "array",
            Value::Table(_) => "table",
        }
    }
    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Table(t) => t.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
}

#[derive(Debug)]
pub struct TomlError {
    pub line: usize,
    pub col: usize,
    pub msg: String,
}

struct P<'a> {
    s: &'a [char],
    i: usize,
}

type R<T> = Result<T, TomlError>;

impl<'a> P<'a> {
    fn pos(&self) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for &c in &self.s[..self.i.min(self.s.len())] {
            if c == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
    fn err<T>(&self, msg: &str) -> R<T> {
        let (line, col) = self.pos();
        Err(TomlError { line, col, msg: msg.to_string() })
    }
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn ws_nl(&mut self) {
        loop {
            self.ws();
            match self.peek() {
                Some('\n') | Some('\r') => self.i += 1,
                Some('#') => {
                    while let Some(c) = self.peek() {
                        if c == '\n' {
                            break;
                        }
                        self.i += 1;
                    }
                }
                _ => break,
            }
        }
    }
    fn line_end(&mut self) -> R<()> {
        self.ws();
        match self.peek() {
            None => Ok(()),
            Some('\n') => {
                self.i += 1;
                Ok(())
            }
            Some('\r') => {
                self.i += 1;
                if self.peek() == Some('\n') {
                    self.i += 1;
                }
                Ok(())
            }
            Some('#') => {
                while let Some(c) = self.peek() {
                    if c == '\n' {
                        break;
                    }
                    self.i += 1;
                }
                Ok(())
            }
            _ => self.err("expected newline, `#`"),
        }
    }
    fn key_part(&mut self) -> R<String> {
        match self.peek() {
            Some('"') => self.basic_string(),
            Some('\'') => self.literal_string(),
            Some(c) if c.is_ascii_alphanumeric() || c == '_' || c == '-' => {
                let s = self.i;
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                Ok(self.s[s..self.i].iter().collect())
            }
            _ => self.err("invalid key"),
        }
    }
    fn dotted_key(&mut self) -> R<Vec<String>> {
        let mut parts = vec![self.key_part()?];
        loop {
            self.ws();
            if self.peek() == Some('.') {
                self.i += 1;
                self.ws();
                parts.push(self.key_part()?);
            } else {
                break;
            }
        }
        Ok(parts)
    }
    fn basic_string(&mut self) -> R<String> {
        self.i += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None | Some('\n') => return self.err("invalid basic string"),
                Some('"') => {
                    self.i += 1;
                    return Ok(out);
                }
                Some('\\') => {
                    self.i += 1;
                    let e = self.peek();
                    self.i += 1;
                    match e {
                        Some('n') => out.push('\n'),
                        Some('t') => out.push('\t'),
                        Some('r') => out.push('\r'),
                        Some('"') => out.push('"'),
                        Some('\\') => out.push('\\'),
                        Some('u') | Some('U') => {
                            let n = if e == Some('u') { 4 } else { 8 };
                            let h: String = self.s[self.i..(self.i + n).min(self.s.len())].iter().collect();
                            self.i += n;
                            match u32::from_str_radix(&h, 16).ok().and_then(char::from_u32) {
                                Some(c) => out.push(c),
                                None => return self.err("invalid unicode escape"),
                            }
                        }
                        _ => return self.err("invalid escape sequence"),
                    }
                }
                Some(c) => {
                    out.push(c);
                    self.i += 1;
                }
            }
        }
    }
    fn literal_string(&mut self) -> R<String> {
        self.i += 1;
        let s = self.i;
        loop {
            match self.peek() {
                None | Some('\n') => return self.err("invalid literal string"),
                Some('\'') => {
                    let v: String = self.s[s..self.i].iter().collect();
                    self.i += 1;
                    return Ok(v);
                }
                _ => self.i += 1,
            }
        }
    }
    fn value(&mut self) -> R<Value> {
        match self.peek() {
            Some('"') => {
                if self.s.get(self.i + 1) == Some(&'"') && self.s.get(self.i + 2) == Some(&'"') {
                    self.i += 3;
                    if self.peek() == Some('\n') {
                        self.i += 1;
                    }
                    let s = self.i;
                    while self.i + 2 < self.s.len() + 0 && !(self.s[self.i] == '"' && self.s[self.i + 1] == '"' && self.s[self.i + 2] == '"') {
                        self.i += 1;
                    }
                    let v: String = self.s[s..self.i.min(self.s.len())].iter().collect();
                    self.i += 3;
