                        i += 1;
                        continue;
                    }
                    None => {}
                }
            }
            out.push(std::mem::take(&mut cur));
        }
        i += 1;
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

pub fn wrap_units(units: &[Unit], wrap: Wrap, first_width: usize, rest_width: usize) -> Option<Vec<String>> {
