fn is_list_label(b: &str) -> bool {
    if b.chars().all(|c| c.is_ascii_digit()) && !b.is_empty() {
        return true;
    }
    if b.chars().count() == 1 && b.chars().next().unwrap().is_ascii_alphabetic() {
        return true;
    }
    if !b.is_empty() && (b.chars().all(|c| "ivxlcdm".contains(c)) || b.chars().all(|c| "IVXLCDM".contains(c))) {
        return true;
    }
    false
