arguments.command:
python3 - <<'EOF'
p='src/markdown/wrap.rs'
s=open(p).read()
old=s[s.index("            let is_attr = p.text.ends_with('\"')"):s.index("            } else {\n                lines.push(format!(\"  {}\", p.text));")]
new='''            // Only a leading `fig-alt` value is wrapped.
            let alt_first = p.text.find('"').map(|q| p.text[..q].ends_with("fig-alt=")).unwrap_or(false);
            let is_attr = alt_first && p.text.ends_with('"') && p.text.contains(' ');
            if is_attr && 2 + width(&p.text) > rest_width {
                // The text wraps like prose without indentation; continuation
                // lines stop one column short and the closing quote is not measured.
                let body = &p.text[..p.text.len() - 1];
                let words: Vec<&str> = body.split(' ').filter(|w| !w.is_empty()).collect();
                let mut line = String::from("  ");
                let mut lw = 2;
                let mut first = true;
                let mut first_line = true;
                for w in words {
                    let ww = width(w);
                    let limit = if first_line { rest_width } else { rest_width.saturating_sub(1) };
                    if first {
                        line.push_str(w);
                        lw += ww;
                        first = false;
                    } else if lw + 1 + ww <= limit {
                        line.push(' ');
                        line.push_str(w);
                        lw += 1 + ww;
                    } else {
                        lines.push(std::mem::take(&mut line));
                        first_line = false;
                        line.push_str(w);
                        lw = ww;
                    }
                }
                line.push('"');
                lines.push(line);
'''
s=s.replace(old,new,1)
open(p,'w').write(s)
