            if value.chars().count() > self.opts.prose_width && fold_eligible(&value) {
                self.append(">-");
                let ci = col + self.opts.indent_width;
                for l in fill_words(&value, self.opts.prose_width) {
                    self.push_line(format!("{}{}", " ".repeat(ci), l));
                }
