        self.col_delta = e.col as isize - col as isize;
        self.value_counted = true;
        self.emit_map_value(e, col, compact_item, preserve);
        if self.value_counted {
            self.stats.emitted_nodes += 1;
        }
        self.value_counted = true;
        self.col_delta = saved;
    }
}

