import sys, json, re
out = []
for f in sys.argv[1:]:
    lines = open(f, encoding="utf-8").read().split("\n")
    name = f.rsplit("/", 1)[1]
    i = 0
    if lines[0] == "---":
        j = lines.index("---", 1)
        out.append({"file": name, "line": 1, "kind": "front", "yaml": "\n".join(lines[1:j]) + "\n"})
        i = j + 1
    while i < len(lines):
        m = re.match(r"^(\s*)(`{3,}|~{3,})\s*\{?([A-Za-z]*)", lines[i])
        if m:
            ind, fence, lang = m.group(1), m.group(2), m.group(3)
            j = i + 1
            while j < len(lines) and not (lines[j].strip().startswith(fence[0] * len(fence)) and set(lines[j].strip()) == {fence[0]}):
                j += 1
            body = [l[len(ind):] if l.startswith(ind) else l.lstrip() for l in lines[i + 1:j]]
            if lang in ("yaml", "yml"):
                out.append({"file": name, "line": i + 1, "kind": "yaml-fence", "yaml": "\n".join(body) + "\n"})
            else:
                hp = []
                for l in body:
                    if l.startswith("#|"):
                        hp.append(l[3:] if l.startswith("#| ") else "")
                    else:
                        break
                if hp:
                    out.append({"file": name, "line": i + 2, "kind": "hashpipe-" + lang, "yaml": "\n".join(hp) + "\n"})
            if lang in ("markdown", "md"):
                i += 1  # descend into nested markdown fences
                continue
            i = j + 1
            continue
        i += 1
print(json.dumps(out))
