close_of = {'(': ')', '[': ']', '{': '}'}
while i < n:
    c = src[i]
    if c == '\n': line += 1; i += 1; continue
    if c == '#':
        j = src.find('\n', i); i = n if j < 0 else j; continue
    m = raw.match(src, i)
    if m and (i == 0 or not (src[i-1].isalnum() or src[i-1] in '._')):
        term = close_of[m.group(2)] + m.group(1) + '"'
        j = src.find(term, m.end())
        if j < 0: sys.exit(f'unterminated raw string at line {line}')
        line += src.count('\n', i, j); i = j + len(term); continue
    if c in '"\'`':
        j = i + 1
        while src[j] != c:
            if src[j] == '\\': j += 1
            j += 1
        line += src.count('\n', i, j); i = j + 1; continue
    if c in '([{': stack.append((c, line))
    elif c in ')]}':
        if not stack or stack[-1][0] != pairs[c]: sys.exit(f'mismatch {c} at line {line}, stack top {stack[-1] if stack else None}')
        stack.pop()
    i += 1
