// GFM pipe table formatting.

use super::inline::collapse_ws;
use super::width::width;
use crate::options::TableWidths;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Align {
    None,
    Left,
    Right,
    Center,
}

/// Split a table row into cells, honoring escapes and code spans.
fn split_row(line: &str) -> Vec<String> {
    let t = line.trim();
    let t = t.strip_prefix('|').unwrap_or(t);
    let chars: Vec<char> = t.chars().collect();
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' && i + 1 < chars.len() {
            cur.push(c);
            cur.push(chars[i + 1]);
            i += 2;
            continue;
        }
        if c == '`' {
            let mut n = 0;
            while i + n < chars.len() && chars[i + n] == '`' {
                n += 1;
            }
            // find closing run
            let mut j = i + n;
            let mut found = None;
            while j < chars.len() {
                if chars[j] == '`' {
                    let mut m = 0;
                    while j + m < chars.len() && chars[j + m] == '`' {
                        m += 1;
                    }
                    if m == n {
                        found = Some(j + m);
                        break;
                    }
                    j += m;
                } else {
                    j += 1;
                }
            }
            match found {
                Some(e) => {
                    cur.extend(&chars[i..e]);
                    i = e;
                }
                None => {
                    cur.extend(&chars[i..i + n]);
                    i += n;
                }
            }
            continue;
        }
        if c == '|' {
            cells.push(std::mem::take(&mut cur));
            i += 1;
            continue;
        }
        cur.push(c);
        i += 1;
    }
    if !cur.trim().is_empty() || !t.trim_end().ends_with('|') {
        cells.push(cur);
    }
    cells.into_iter().map(|c| collapse_ws(c.trim())).collect()
}

