    words.iter().try_for_each(|w| check_option_word(w))?;
    if let [sc] = words {
        if let Some(s) = sc.strip_prefix("scope=").filter(|s| *s != "next") {
            return Err(format!("fmt: markdown with scope={} requires at least one option", s));
