new="""/// End of the group closed by `close` that opens at `i` (nesting aware).
fn group_end(chars: &[char], i: usize, open: char, close: char) -> Option<usize> {
    let mut depth = 0;
    let mut j = i;
    while j < chars.len() {
        if chars[j] == '\\\\' {
            j += 2;
            continue;
        }
        if chars[j] == open {
            depth += 1;
        } else if chars[j] == close {
            depth -= 1;
            if depth == 0 {
                return Some(j + 1);
            }
        }
        j += 1;
    }
    None
}

/// Whether prose outside code, math, links, braces and HTML holds a backslash
/// before a letter (a raw TeX command).
fn has_text_tex_command(chars: &[char]) -> bool {
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let skip = match c {
            '\\\\' => {
                if chars.get(i + 1).is_some_and(|c| c.is_alphabetic()) {
                    return true;
                }
                Some(i + 2)
            }
            '`' => Some(code_span_end(chars, i).unwrap_or(i + backtick_run(chars, i))),
            '$' => math_end(chars, i),
            '[' => bracket_end(chars, i).map(|e| match chars.get(e + 1) {
                Some('(') => group_end(chars, e + 1, '(', ')').unwrap_or(e + 1),
                Some('[') => bracket_end(chars, e + 1).map_or(e + 1, |f| f + 1),
                _ => e + 1,
            }),
            '{' => group_end(chars, i, '{', '}'),
            '<' => autolink_end(chars, i).or_else(|| {
                html_tag_at(chars, i).map(|(e, name, close, selfc)| {
                    if close || selfc || VOID_TAGS.contains(&name.as_str()) {
                        e
                    } else {
                        html_element_end(chars, e, &name).unwrap_or(e)
                    }
                })
            }),
            _ => None,
        };
        i = skip.unwrap_or(i + 1);
    }
    false
}

