new="""/// Line endings for a file mixing CRLF and LF lines: an output line takes the
/// ending of the source line it comes from, and lines reflowed together take the
/// ending of the last source line among them. Lines are matched through their
/// words.
fn restore_mixed_eol(text: &str, normalized: &str, out: &str) -> String {
    let src_lines: Vec<&str> = normalized.strip_suffix('\\n').unwrap_or(normalized).split('\\n').collect();
    let raw_lines: Vec<&str> = text.split('\\n').collect();
    let crlf: Vec<bool> = (0..src_lines.len()).map(|i| raw_lines.get(i).is_some_and(|l| l.ends_with('\\r'))).collect();
    let body = out.strip_suffix('\\n');
    let out_lines: Vec<&str> = body.unwrap_or(out).split('\\n').collect();
    let (n, m) = (src_lines.len(), out_lines.len());
    let src_tokens: Vec<(&str, usize)> = src_lines.iter().enumerate().flat_map(|(i, l)| l.split_whitespace().map(move |t| (t, i))).collect();
    // Union-find over output lines (0..m) and source lines (m..m+n).
    let mut parent: Vec<usize> = (0..m + n).collect();
    fn find(p: &mut [usize], x: usize) -> usize {
        let mut r = x;
        while p[r] != r {
            r = p[r];
        }
        let mut y = x;
        while p[y] != r {
            let next = p[y];
            p[y] = r;
            y = next;
        }
        r
    }
    let mut next = 0;
    for (j, l) in out_lines.iter().enumerate() {
        for t in l.split_whitespace() {
            if let Some(k) = src_tokens[next.min(src_tokens.len())..].iter().take(64).position(|(s, _)| *s == t) {
                let (_, i) = src_tokens[next + k];
                let (a, b) = (find(&mut parent, j), find(&mut parent, m + i));
                parent[a] = b;
                next += k + 1;
            }
        }
    }
    let mut last_src: Vec<Option<usize>> = vec![None; m + n];
    for i in 0..n {
        let r = find(&mut parent, m + i);
        last_src[r] = Some(last_src[r].map_or(i, |x| x.max(i)));
    }
    let mut res = String::new();
    let mut frontier = 0;
    for (j, l) in out_lines.iter().enumerate() {
        let r = find(&mut parent, j);
        let src = match last_src[r] {
            Some(i) => {
                frontier = frontier.max(i + 1);
                i
            }
            None => frontier.min(n.saturating_sub(1)),
        };
        res.push_str(l);
        if j + 1 < m || body.is_some() {
            res.push_str(if crlf.get(src).copied().unwrap_or(false) { "\\r\\n" } else { "\\n" });
        }
    }
    res
}

